/// Icons8 SVG를 패널 아이콘 색으로 그린다. [angle]은 라디안.
class StudentDetailIcon extends StatelessWidget {
  const StudentDetailIcon(
    this.svg, {
    super.key,
    this.size = 18,
    this.color,
    this.angle = 0,
  });

  final String svg;
  final double size;
  final Color? color;
  final double angle;

  @override
  Widget build(BuildContext context) {
    final iconColor = color ??
        FabTabBarTokens.previewAcademyPanelStyleFor(
          Theme.of(context).brightness,
        ).icon;
    final picture = SvgPicture.string(
      svg,
      width: size,
      height: size,
      colorFilter: ColorFilter.mode(iconColor, BlendMode.srcIn),
    );
    if (angle == 0) return picture;
    return Transform.rotate(angle: angle, child: picture);
  }
}

PreviewAcademyPanelStyle studentDetailPanel(BuildContext context) {
  return FabTabBarTokens.previewAcademyPanelStyleFor(
    Theme.of(context).brightness,
  );
}

BoxDecoration studentDetailCardDecoration(BuildContext context) {
  final brightness = Theme.of(context).brightness;
  return PreviewAcademyGroupedFieldsCard.cardDecoration(
    studentDetailPanel(context),
    brightness: brightness,
  );
}

ButtonStyle studentDetailPillStyle(
  BuildContext context, {
  bool accent = false,
  bool danger = false,
  bool border = true,
}) {
  final style = studentDetailPanel(context);
  final brightness = Theme.of(context).brightness;
  const dangerColor = Color(0xFFE57373);
  final foreground = danger
      ? dangerColor
      : (accent ? style.changeButtonText : style.title);
  // 채움이 없는 버튼. 다크는 카드 위 투명, 라이트는 흰 바탕이라 회색으로 묻히지 않는다.
  final neutralFill = brightness == Brightness.light
      ? style.dropdownBackground
      : Colors.transparent;
  final neutralBorder = brightness == Brightness.light
      ? FabTabBarTokens.groupedCardBorderFor(brightness).top.color
      : style.border;
  return TextButton.styleFrom(
    backgroundColor: accent ? style.changeButtonBackground : neutralFill,
    foregroundColor: foreground,
    padding: const EdgeInsets.symmetric(horizontal: 16),
    minimumSize: const Size(0, AppDialogActionMetrics.height),
    maximumSize: const Size(double.infinity, AppDialogActionMetrics.height),
    tapTargetSize: MaterialTapTargetSize.shrinkWrap,
    shape: RoundedRectangleBorder(
      borderRadius: BorderRadius.circular(999),
      side: border
          ? BorderSide(
              color: danger
                  ? dangerColor
                  : (accent ? Colors.transparent : neutralBorder),
            )
          : BorderSide.none,
    ),
    textStyle: TextStyle(
      fontFamily: FabTabBarTokens.previewAcademyLabelFontFamily,
      fontSize: FabTabBarTokens.previewAcademyBaseFontSize,
      fontWeight: FontWeight.w600,
      color: foreground,
    ),
  );
}

double get studentDetailChevronLeft => math.pi;

double get studentDetailChevronDown => math.pi / 2;
